import json, re, sys

d = json.load(open(sys.argv[1], encoding='utf-8'))
T = {x['doc_id']: x['text'] for x in d['documents']}
LADDER = [40, 60, 100, 200, 300, 500, 800, 1500, 2500, 4000]
recs = {}  # sample -> dict(cond, S, v, src)


def put(sid, cond, S, v, src):
    if sid in recs:
        raise SystemExit(f'duplicate {sid} from {src} and {recs[sid]["src"]}')
    recs[sid] = dict(cond=cond, S=float(S), v=float(v), src=src)


# D4 raw export (µmol/L/min == µM/min); S and condition from notebooks
d4 = {}
for line in T['D4'].splitlines():
    m = re.match(r'^\s*(\d+)\s+([A-H]\d\d)\s+(HV-\d{4})\s+([\d.]+)\s+', line)
    if m:
        d4[m.group(3)] = float(m.group(4)) / 60.0
d4_cond = {}
for i in range(10):
    d4_cond[f'HV-{547+i:04d}'] = 'C5'
    d4_cond[f'HV-{537+i:04d}'] = 'C8'
    d4_cond[f'HV-{397+i:04d}'] = 'C3'
    d4_cond[f'HV-{232+i:04d}'] = 'C4'
    d4_cond[f'HV-{175+i:04d}'] = 'C8'
d4_S = {}
for i in range(10):
    for base in (547, 537, 397, 232, 175):
        d4_S[f'HV-{base+i:04d}'] = LADDER[i]
assert len(d4) == 50, len(d4)
for sid, v in d4.items():
    put(sid, d4_cond[sid], d4_S[sid], v, 'D4')

# D6 Priya CSV (nM/s)
def d6_cond(lbl):
    return {'37 °C, pH 5.5': 'C3', 'pH 7.4 / 30 °C + MPX-9 5 µM': 'C1',
            '30 °C, pH 7.4, MPX-9 at 0.005 mM': 'C1',
            'pH 7.4, 30 °C + MPX-9 200 µM': 'C7'}[lbl]
import csv
block = T['D6'].split('sample_id,', 1)[1].split('```', 1)[0]
for row in csv.reader(['sample_id,' + block.strip()] if False else [l for l in ('sample_id,' + block).splitlines() if l.strip()]):
    if not row or not row[0].startswith('HV-'):
        continue
    sid, cond_lbl, S, rate, qc = row[0], row[3], row[5], row[6], row[8]
    v = float(rate.replace('×10^', 'e'))
    m = re.search(r're-read: ([\d.]+)', qc)
    if m:
        v = float(m.group(1))  # re-read replaces first reading
    put(sid, d6_cond(cond_lbl), S, v / 1000.0, 'D6')

# D7 Mikael instrument export (decimal comma, µM/min)
d7_cond = {'Coral block': 'C7', 'Slate block': 'C2', 'Granite block': 'C5'}
body = T['D7'].split('sample;plate;well;condition;rep;S_uM;rate_uM_per_s;remark', 1)[1].split('```', 1)[0]
for line in body.splitlines():
    if not line.startswith('HV-'):
        continue
    f = line.split(';', 7)
    put(f[0], d7_cond[f[3]], f[5], float(f[6].replace(',', '.')) / 60.0, 'D7')

# D9 Leila summary (µM/s)
cur = None
for line in T['D9'].splitlines():
    m = re.match(r'Condition: (?:condition )?(C\d)', line)
    if m:
        cur = m.group(1)
        continue
    m = re.match(r'\s*\[S\] = (\d+) µM: r\d ([\d.Ee+-]+) \((HV-\d{4})\)', line)
    if m:
        put(m.group(3), cur, m.group(1), float(m.group(2)), 'D9')

# D10 Hamid bench log (µM/s), typed by hand from prose
for i, v in enumerate([0.350, 0.318, 0.207, 0.0797, 0.702, 0.126, 0.672, 0.0554, 0.605, 0.476]):
    put(f'HV-{159+i:04d}', 'C8', [500, 300, 200, 60, 4000, 100, 2500, 40, 1500, 800][i], v, 'D10-Violet-relabelled')
for i, v in enumerate([0.0975, 0.132, 0.222, 0.383, 0.501, 0.683, 0.791, 1.06, 1.12, 1.27]):
    put(f'HV-{379+i:04d}', 'C5', LADDER[i], v, 'D10-Granite')

# D12 Bram + D14 Ines (Celvex slopes, mAU/min -> µM/s)
hdr_map = {'C4': 'C4', 'C6': 'C6', 'C8': 'C8', 'Blue block': 'C4', 'Amber block': 'C3',
           'Coral block': 'C7', 'Saffron block': 'C8'}
EPS_L = 6.22 * 0.6  # mM^-1 * (ε·l) -> µM/min = |mAU/min|/1000/(ε·l)*1000
for doc in ('D12', 'D14'):
    cond = None
    for line in T[doc].splitlines():
        m = re.match(r'Plate \d+ \| Assay: (.*?) \|', line)
        if m:
            cond = hdr_map[m.group(1).replace('condition ', '')]
            continue
        m = re.match(r'^([A-H]\d\d)\s+(HV-\d{4})\s+([\d.]+)\s*(µM|uM|mM)\s+(-?[\d.]+)\s+([\d.]+)', line)
        if m:
            S = float(m.group(3)) * (1000 if m.group(4) == 'mM' else 1)
            slope = abs(float(m.group(5)))
            v = slope / EPS_L / 60.0 / 1000.0 * 1000.0 / 1000.0  # placeholder fixed below
            put(m.group(2), cond, S, v, doc)

# D15 Ana notebook (mM/min -> µM/s)
cond = None
for line in T['D15'].splitlines():
    m = re.match(r'### Plate \d+, (?:cond(?:ition)? )?(C\d)', line)
    if m:
        cond = m.group(1)
        continue
    m = re.match(r'\|\s*(HV-\d{4})\s*\|\s*[A-H]\d\d\s*\|\s*([\d.]+)\s*\|\s*([\d.e-]+)\s*\|', line)
    if m:
        put(m.group(1), cond, m.group(2), float(m.group(3)) * 1000.0 / 60.0, 'D15')

print('n records', len(recs))
json.dump(recs, open('/tmp/hvwork/recs_raw.json', 'w'), indent=1, ensure_ascii=False)

import json, math, sys

recs = json.load(open('/tmp/hvwork/recs_raw.json'))

# Section 4 corrections (authors' own statements, not withdrawn)
for i in range(488, 498):                      # Bram: entered as C8, really pH 9.0 = C5
    recs[f'HV-{i:04d}']['cond'] = 'C5'
recs['HV-0320']['S'], recs['HV-0328']['S'] = 4000.0, 40.0   # Ines: [S] labels swapped

# Section 2 exclusions
excluded = {
    'HV-0300': 'SAT, plate 6 row C top [S] (Mikael addendum)',
    'HV-0214': 'OVR, plate 5 row D top [S] (Mikael)',
    'HV-0580': 'bubble 4 min before read end (Mikael D7)',
    'HV-0508': 'block temp 39.2 C vs 37 C setpoint (Leila D9)',
    'HV-0254': 'block temp 38.6 C vs 37 C setpoint (Ines D14)',
    'HV-0195': 'tip slipped during enzyme dispense (Ana D15)',
    'HV-0339': 'substrate added 2 min late, plate 7 row A 9th from right (Ana chat)',
    'HV-0180': 'bubble during read, moved from HV-0179 by Ana addendum',
    'HV-0239': 'bubble 2 min into read (Hamid D10, follows HV-0239 entry)',
    'HV-0323': 'substrate added 2 min late (Ines, ID corrected from HV-0566)',
    'HV-0571': 'bubble 3 min after read start (Ines addendum)',
}
for sid in excluded:
    assert sid in recs, sid
    print('excluded', sid, recs[sid]['cond'], recs[sid]['S'], excluded[sid])

# Section 5 dilution rescale: C4 master mix (Blue block) made at 1:250 -> x0.5
for r in recs.values():
    if r['cond'] == 'C4':
        r['v'] *= 0.5

def ssr_vmax(km, pts):
    xs = [s / (km + s) for s, _ in pts]
    vmax = sum(v * x for x, (_, v) in zip(xs, pts)) / sum(x * x for x in xs)
    return vmax, sum((v - vmax * x) ** 2 for x, (_, v) in zip(xs, pts))

def ssr_fixed(km, vmax, pts):
    return sum((v - vmax * s / (km + s)) ** 2 for s, v in pts)

def golden(f, a, b, tol=1e-10):
    g = (math.sqrt(5) - 1) / 2
    c, d = b - g * (b - a), a + g * (b - a)
    while abs(b - a) > tol * (1 + abs(a)):
        if f(c) < f(d):
            b = d
        else:
            a = c
        c, d = b - g * (b - a), a + g * (b - a)
    return (a + b) / 2

def profile(pts, fn):
    # coarse log grid then refine around best
    grid = [10 ** (-2 + 8 * k / 4000) for k in range(4001)]
    best = min(grid, key=lambda km: fn(km))
    lo, hi = best / 1.01, best * 1.01
    return golden(fn, lo, hi)

def fit_free(pts):
    km = profile(pts, lambda k: ssr_vmax(k, pts)[1])
    vmax, _ = ssr_vmax(km, pts)
    return vmax, km

def fit_km_only(pts, vmax):
    km = profile(pts, lambda k: ssr_fixed(k, vmax, pts))
    return km

conds = {}
for cid in ['C1', 'C2', 'C3', 'C4', 'C5', 'C6', 'C7', 'C8']:
    pts = [(r['S'], r['v']) for sid, r in recs.items()
           if r['cond'] == cid and sid not in excluded]
    conds[cid] = pts
    print(cid, 'n=', len(pts))

out = {}
for cid in ['C2', 'C3', 'C4', 'C5', 'C8']:
    out[cid] = fit_free(conds[cid])
# inhibitor conditions: Vmax shared with matching no-inhibitor condition
out['C1'] = (out['C8'][0], fit_km_only(conds['C1'], out['C8'][0]))
out['C7'] = (out['C8'][0], fit_km_only(conds['C7'], out['C8'][0]))
out['C6'] = (out['C4'][0], fit_km_only(conds['C6'], out['C4'][0]))

for cid in ['C1', 'C2', 'C3', 'C4', 'C5', 'C6', 'C7', 'C8']:
    print(cid, 'Vmax=%.5f Km=%.3f' % out[cid], 'n=', len(conds[cid]))

answer = {
    'conditions': [{'condition_id': c, 'vmax': round(out[c][0], 6), 'km': round(out[c][1], 4)}
                   for c in ['C1', 'C2', 'C3', 'C4', 'C5', 'C6', 'C7', 'C8']],
    'excluded_samples': sorted(excluded),
}
json.dump(answer, open('/tmp/hvwork/answer_draft.json', 'w'), indent=1)
print(json.dumps(answer, indent=1))

